  // --- Integrity ---
  "adminAudit.integrity.title": "Integrity & Tamper Evidence",
  "adminAudit.integrity.subtitle":
    "Whether the audit log still proves itself — the daily seals and the hash-chain verdict.",
  "adminAudit.integrity.how.title": "How this is checked",
  "adminAudit.integrity.how.body":
    "Each event's hash covers the hash of the event before it, so changing any past event would break every hash after it. At 02:15 IST each night the server re-walks the previous day's chain and writes a sealed record: the day's event range, its row count and the final hash.",
  "adminAudit.integrity.how.noManual":
    "There is no “verify now” button here. Re-walking the chain runs on the server with its own credentials; a browser cannot do it. What you see below is the server's own verdict and when it reached it.",
  "adminAudit.integrity.windowHint": "Seals are kept for every day; the default view is the last 90.",
  "adminAudit.integrity.checksLabel": "the verifier's own findings",
  "adminAudit.integrity.alert.title": "The audit log does not verify",
  "adminAudit.integrity.alert.body":
    "At least one day's hash chain did not reproduce. Treat the audit log as disputed and investigate before running any further maintenance on it. Do not export it as evidence until this is resolved.",
  "adminAudit.integrity.kpi.chain": "Chain state",
  "adminAudit.integrity.kpi.chainOk": "Verifies",
  "adminAudit.integrity.kpi.chainBroken": "Broken",
  "adminAudit.integrity.kpi.chainStale": "Not yet verified",
  "adminAudit.integrity.kpi.chainFormula":
    "The verdict the server recorded on the most recent seal in this window, and whether any seal in it reports a break.",
  "adminAudit.integrity.kpi.lastSealed": "Last sealed day",
  "adminAudit.integrity.kpi.lastVerified": "Verified {when}",
  "adminAudit.integrity.kpi.lastSealedFormula":
    "The newest seal in this window. Today is normally unsealed until the 02:15 IST job runs.",
