  "admin.akiosk.rate.title": "Match rate by day",
  "admin.akiosk.rate.caption":
    "One line per device, plotting v_kiosk_health.match_success_pct — computed in SQL as matched × 100 ÷ attempts for that device on that day. A break in the line is a day the gate saw no scans, not a failure.",
  "admin.akiosk.rate.empty.title": "No scans in this window",
  "admin.akiosk.rate.empty.hint":
    "v_kiosk_health has a row only for a device-day with at least one attempt, so an empty window means the gate was not used.",
  "admin.akiosk.latency.title": "Recognition latency (95th percentile)",
  "admin.akiosk.latency.caption":
    "v_kiosk_health.p95_latency_ms per device per day, computed by Postgres with percentile_disc. The 95th percentile is what the slowest scans feel like, which is what a queue at the gate actually experiences.",
  "admin.akiosk.latency.empty.title": "No latency to show",
  "admin.akiosk.latency.empty.hint":
    "Latency percentiles exist only for a device-day that recorded attempts. Widen the window or pick another device.",
  "admin.akiosk.outcomes.title": "Outcomes by day — {device}",
  "admin.akiosk.outcomes.caption":
    "Four of the view's own columns, stacked: matched, no match, ambiguous and liveness failures. Capture failures, engine errors and suppressed duplicates are deliberately NOT folded into an 'other' band, because adding three columns together here would be arithmetic this screen must not do — they are columns in the table below.",
  "admin.akiosk.outcomes.pick.title": "Pick one device to see its outcomes",
  "admin.akiosk.outcomes.pick.hint":
    "Stacking two devices' counts into one bar would mean adding them up in the browser. Choose a device above and the day-by-day breakdown appears.",
  "admin.akiosk.outcomes.empty.title": "No outcomes for this device",
  "admin.akiosk.outcomes.empty.hint": "This device recorded no attempts in the selected window.",
