  "admin.akiosk.col.capture": "Capture",
  "admin.akiosk.col.errors": "Errors",
  "admin.akiosk.col.duplicates": "Duplicates",
  "admin.akiosk.col.p50": "p50",
  "admin.akiosk.col.p95": "p95",
  "admin.akiosk.col.offline": "Offline replays",
  "admin.akiosk.col.lastSeen": "Last heartbeat",
  "admin.akiosk.grid.empty.title": "No kiosk health rows",
  "admin.akiosk.grid.empty.hint":
    "One row per device per IST day that saw a scan. An empty grid means no scans in the window, not a broken camera — check the heartbeat on System Health.",
  "admin.akiosk.note.noFleetRate":
    "There is no fleet-wide match rate on this screen because no view computes one. A rate cannot be added up, and averaging each day's percentage would weight a three-scan Sunday like a two-hundred-scan Saturday. The tiles are counts; the rate is shown per device per day, exactly where the server computes it.",
  "admin.akiosk.note.rowCap":
    "The grid reads at most 500 device-days. Narrow the window if a longer period is needed — the tile counts are Postgres counts and stay correct regardless.",
  "admin.akiosk.note.seriesCap":
    "Only {shown} of {total} devices are plotted: this palette cannot keep more than {shown} lines apart for a colour-blind reader. Pick a device to see it on its own; every device is in the table below.",

