  "admin.acomp.docs.hint":
    "Soonest expiry first. The server flags a document as lapsing soon {days} days out; that window is the view's, not this screen's.",
  "admin.acomp.docs.empty.title": "Nothing to chase",
  "admin.acomp.docs.empty.hint":
    "Every required document for the current filter is on file and in date. Change the state filter to see valid ones too.",
