  "admin.apiKeys.notice.noClientPath": "This browser cannot read, issue, rotate or revoke an API key. The table lives in a schema that grants no access to signed-in users, and the edge function meant to manage it is not deployed. Nothing below is a hidden control — it is a list of what is missing.",
  "admin.apiKeys.empty.title": "No API key register is available",
  "admin.apiKeys.empty.hint": "Rather than show an empty grid that can never fill, this screen names the pieces that would have to exist first.",
  "admin.apiKeys.cards.title": "What exists, what does not, and where the work happens",
  "admin.apiKeys.cards.subtitle": "Each card names the exact database object or function involved, so an engineer can act on it without guessing.",
  "admin.apiKeys.badge.missing": "Not available",
  "admin.apiKeys.badge.elsewhere": "Handled elsewhere",
  "admin.apiKeys.card.keys.title": "API key register",
  "admin.apiKeys.card.keys.body": "Keys are stored hashed, with a prefix, scopes, a rate limit and an expiry. All of it is unreachable from a browser: access is revoked at both the table and the schema, and the management function was never deployed.",
  "admin.apiKeys.card.keys.evidence": "secure.api_keys — revoked from anon and authenticated; schema secure grants no usage; edge function admin-api-keys absent",
  "admin.apiKeys.card.webhooks.title": "Outbound webhooks",
  "admin.apiKeys.card.webhooks.body": "Endpoints, signing secrets, the delivery log and replay have no table anywhere in the database, so there is nothing to list and nothing to retry.",
  "admin.apiKeys.card.webhooks.evidence": "no webhooks / webhook_endpoints / webhook_deliveries table in any migration",
  "admin.apiKeys.card.kiosk.title": "Kiosk device credentials",
  "admin.apiKeys.card.kiosk.body": "The machine credentials this system really issues today belong to the gate tablets, and they are provisioned and revoked on the kiosk devices screen.",
  "admin.apiKeys.card.kiosk.evidence": "edge functions kiosk-provision and kiosk-device-activate",
  "admin.apiKeys.card.kiosk.link": "Open kiosk devices",
  "admin.apiKeys.card.providers.title": "Provider credentials",
  "admin.apiKeys.card.providers.body": "Email, SMS, AI, banking and accounting credentials are function secrets held outside the database. The integrations screen shows which secret each provider reads, by name.",
  "admin.apiKeys.card.providers.evidence": "integrations.config holds secret names only; values are Supabase function secrets",
  "admin.apiKeys.card.providers.link": "Open integrations",
  "admin.apiKeys.footnote": "A credential screen that guessed would be worse than none: it would imply keys had been checked when they had not. Everything above was read from the deployed migrations and the deployed function list.",

