  "team.roster.noTeam.title": "Nobody reports to you",
  "team.roster.noTeam.hint": "This screen fills itself the moment a reporting line points at you.",
  "team.roster.gap.noWrite":
    "Publishing is not offered here, and is not being faked. Migration 015 routes roster slot writes through a roster edge function, no such function is deployed, and no publish_roster RPC exists in any migration — even though the roster.publish capability is already modelled for managers. The endpoint has to be built server-side.",
  "team.roster.gap.noEvents":
    "Event staffing needs cannot be shown: public.events does not exist on this backend. Every slot's event_id is null and its foreign key is still waiting for the event register, so there is no booking to plan against.",
  "team.roster.footnote":
    "One row per person per date, exactly as the roster holds it. A weekly off is a slot row; an empty cell is the absence of a row, which no filter can count. Draft slots are visible to you because you manage the person — the employee sees only published ones.",

  // §D · /team/analytics — Team Analytics ---------------------------------------
  "team.analytics.title": "Team Analytics",
  "team.analytics.subtitle": "{n} reportees — every figure from the metric dictionary.",
  "team.analytics.tile.late": "Late days",
  "team.analytics.tile.earlyExit": "Early exits",
  "team.analytics.tile.absent": "Absent days",
  "team.analytics.tile.leave": "Days on leave",
  "team.analytics.tile.exceptions": "Days with an anomaly",
  "team.analytics.chart.person": "Person",
  "team.analytics.measure.attendance": "Attendance %",
  "team.analytics.measure.late": "Late days",
  "team.analytics.measure.worked": "Average worked per working day",
  "team.analytics.measure.breaks": "Break time",
  "team.analytics.chart.attendance.title": "Attendance % by person",
  "team.analytics.chart.attendance.caption":
    "{month}. Each bar is that person's attendance_pct from f_attendance_period_summary — computed and clamped by Postgres, not derived here.",
  "team.analytics.chart.late.title": "Late days by person",
  "team.analytics.chart.late.caption":
    "{month}. The count of days the engine marked late for that person, against their own shift and grace.",
  "team.analytics.chart.worked.title": "Average worked per working day",
  "team.analytics.chart.worked.caption":
    "{month}. Averaged by Postgres over the days it counted as working days; a person with no working days has no bar rather than a zero.",
  "team.analytics.chart.breaks.title": "Break time by person",
  "team.analytics.chart.breaks.caption":
    "{month}. Total break minutes the engine derived from break scans. Nobody scanning for breaks reads as no data, not as no breaks.",
  "team.analytics.trend.title": "Attendance % over six months",
  "team.analytics.trend.caption":
    "One line per person, one point per month, each point that person's own server value for that month. There is no single team line, because a team-wide percentage would be an aggregate of aggregates and no deployed relation computes one.",
  "team.analytics.trend.xHeader": "Month",
  "team.analytics.trend.empty": "No reportee to trend yet.",
  "team.analytics.trend.clipped":
    "{drawn} of {total} people are plotted. The chart palette separates four series safely and refuses to invent a fifth colour; the table under the chart lists the drawn lines.",
  "team.analytics.empty.title": "No summary for this month",
  "team.analytics.empty.hint":
    "The metric function returned no row for your team this month — usually because the engine has not computed any day in it yet.",
  "team.analytics.noTeam.title": "Nobody reports to you",
  "team.analytics.noTeam.hint": "Analytics appear as soon as a reporting line points at you.",
  "team.analytics.gap.noPunches":
    "There is no punch-level or gate-level analysis here: v_team_punches is named only in migration comments and was never created. The per-date late and break trend views are org-wide and carry no employee column, so reading them on a manager screen would mix your own days into your team's picture.",
  "team.analytics.footnote":
    "Late %, attendance %, paid days and the averages all come from f_attendance_period_summary — the one implementation of the metric dictionary — so this screen, /team/attendance and payroll cannot disagree. The tiles are Postgres counts over the same days the attendance screen opens.",

