    "Planned versus actually present is not shown. The engine records attendance_days.roster_slot_id, but the day view does not project it and roster_slots.attendance_day_id is never written — so neither side of that join is readable from a browser. Matching by date alone would credit an unrostered person's punches to the plan.",
